"""Authenticated local API and background stream lifecycle."""

from __future__ import annotations

import json
import logging
import os
import re
import secrets
import threading
import time
from http import HTTPStatus
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from pathlib import Path
from urllib.parse import urlsplit

from .bridge import Bridge
from .control import (
    ConfirmationRequired,
    ControlDisabled,
    ControlError,
    ControlManager,
    RateLimited,
)
from .provider import Client, ProviderError
from .restream import Go2Rtc

LOG = logging.getLogger("md_parking_bridge")
VERSION = "0.5.1"
OPTIONS = Path("/data/options.json")
TOKEN_FILE = Path("/data/bridge_api_token")
SESSION_FILE = Path("/data/provider_session.json")
PAIRING_FILE = Path("/data/pairing_complete")
AUDIT_FILE = Path("/data/control_audit.json")
APP = {"os": "android", "ver": "2.0.6"}
AUTH_URL = "https://auth.mdparking.ru/v2/"
SESSION_REFRESH_SECONDS = 240
MAX_BODY_BYTES = 8192


class State:
    """Shared runtime state. Provider identifiers never leave this object graph."""

    def __init__(self) -> None:
        self.started_at = time.time()
        self.lock = threading.RLock()
        self.bridge: Bridge | None = None
        self.last_failure: str | None = None
        self.last_success_at: float | None = None
        self.auth_state = "not_authenticated"
        self.session_refresh_at = 0.0
        self.worker_started = False
        self.options = self._load_options()
        self.pairing_enabled = bool(self.options.get("pairing_enabled", False))
        self.paired = PAIRING_FILE.exists()
        self.control = ControlManager(
            bool(self.options.get("control_enabled", False)),
            self._integer_option("control_cooldown_seconds", 15, 10, 300),
            AUDIT_FILE,
        )
        self.client = Client(AUTH_URL, APP, "mdparking", "")
        if self.client.load_session(SESSION_FILE):
            self._activate_session(refresh=True)

    @staticmethod
    def _load_options() -> dict:
        try:
            value = json.loads(OPTIONS.read_text(encoding="utf-8"))
        except (FileNotFoundError, OSError, UnicodeDecodeError, json.JSONDecodeError):
            LOG.warning("add-on options could not be read; safe defaults are active")
            return {}
        return value if isinstance(value, dict) else {}

    def _integer_option(
        self, name: str, default: int, minimum: int, maximum: int
    ) -> int:
        try:
            value = int(self.options.get(name, default))
        except (TypeError, ValueError):
            return default
        return min(maximum, max(minimum, value))

    def _activate_session(self, refresh: bool = False) -> None:
        """Validate a session by discovery before publishing a new bridge."""
        with self.lock:
            try:
                refreshed = False
                if refresh:
                    try:
                        self.client.refresh_session()
                        self.client.save_session(SESSION_FILE)
                        refreshed = True
                    except ProviderError as exc:
                        LOG.warning(
                            "provider session refresh deferred: %s", exc.safe_code
                        )
                retry = self._integer_option("refresh_retry_seconds", 10, 5, 300)
                self.session_refresh_at = time.monotonic() + (
                    SESSION_REFRESH_SECONDS if refreshed or not refresh else retry
                )
                refresh_before = self._integer_option(
                    "refresh_before_expiry_seconds", 15, 5, 55
                )
                candidate = Bridge(self.client, Go2Rtc(), max(5, 60 - refresh_before))
                candidate.discover()
                if not candidate.cameras:
                    raise ProviderError("no cameras available", "no_cameras")
                candidate.refresh_due()
                self.bridge = candidate
                self.auth_state = "authenticated"
                self.last_failure = None
                self.last_success_at = time.time()
                if not self.worker_started:
                    self.worker_started = True
                    threading.Thread(
                        target=self._loop,
                        name="md-parking-refresh",
                        daemon=True,
                    ).start()
            except ProviderError as exc:
                self.auth_state = "authentication_failed"
                self.last_failure = "provider_session_failed"
                LOG.error("provider session activation failed: %s", exc.safe_code)
            except Exception:
                self.auth_state = "authentication_failed"
                self.last_failure = "provider_session_failed"
                LOG.error("provider session activation failed: internal_error")

    def _loop(self) -> None:
        while True:
            failed = False
            try:
                with self.lock:
                    if time.monotonic() >= self.session_refresh_at:
                        try:
                            self.client.refresh_session()
                            self.client.save_session(SESSION_FILE)
                            self.session_refresh_at = (
                                time.monotonic() + SESSION_REFRESH_SECONDS
                            )
                        except ProviderError as exc:
                            failed = True
                            self.last_failure = "session_refresh_failed"
                            self.session_refresh_at = (
                                time.monotonic()
                                + self._integer_option(
                                    "refresh_retry_seconds", 10, 5, 300
                                )
                            )
                            LOG.warning(
                                "provider session refresh failed: %s", exc.safe_code
                            )
                    if self.bridge is not None:
                        try:
                            self.bridge.refresh_due()
                        except ProviderError as exc:
                            failed = True
                            self.last_failure = "stream_refresh_failed"
                            LOG.warning("stream refresh failed: %s", exc.safe_code)
                        except Exception:
                            failed = True
                            self.last_failure = "stream_refresh_failed"
                            LOG.error("stream refresh failed: internal_error")
                    if not failed:
                        self.last_failure = None
                        self.last_success_at = time.time()
            except Exception:
                self.last_failure = "background_worker_failed"
                LOG.error("background worker failed: internal_error")
            time.sleep(5)

    def request_code(self, phone: str, object_id: str | None) -> str:
        normalized_object = object_id.strip() if object_id else None
        if normalized_object == "":
            raise ValueError("empty object number")
        with self.lock:
            self.client.request_code(self._phone(phone), normalized_object)
            self.auth_state = (
                "code_requested" if normalized_object else "object_required"
            )
        return self.auth_state

    def authorize(self, phone: str, object_id: str, code: str) -> None:
        object_id = object_id.strip()
        code = code.strip()
        if not object_id or not code:
            raise ValueError("missing authentication field")
        with self.lock:
            self.client.authorize(self._phone(phone), object_id, code)
            self.client.save_session(SESSION_FILE)
            self._activate_session()
            if self.auth_state != "authenticated":
                raise ProviderError("session activation failed", "activation_failed")

    @staticmethod
    def _phone(value: str) -> str:
        digits = re.sub(r"\D", "", value)
        if len(digits) == 10:
            digits = "7" + digits
        elif len(digits) == 11 and digits.startswith("8"):
            digits = "7" + digits[1:]
        if len(digits) != 11 or not digits.startswith("7"):
            raise ValueError("invalid phone format")
        return digits

    def diagnostics(self) -> dict:
        bridge = self.bridge
        return {
            "version": VERSION,
            "ready": self.auth_state == "authenticated" and bridge is not None,
            "read_only": not self.control.enabled,
            "control_enabled": self.control.enabled,
            "pairing_enabled": self.pairing_enabled,
            "auth_state": self.auth_state,
            "camera_count": len(bridge.cameras) if bridge else 0,
            "barrier_count": len(bridge.barriers) if bridge else 0,
            "last_failure": self.last_failure,
            "last_success_age_seconds": (
                int(max(0, time.time() - self.last_success_at))
                if self.last_success_at
                else None
            ),
            "uptime_seconds": int(time.time() - self.started_at),
            "cameras": bridge.camera_status() if bridge else [],
            "audit_event_count": len(self.control.audit()),
        }


class BridgeHttpServer(ThreadingHTTPServer):
    daemon_threads = True
    allow_reuse_address = True


def handler_factory(state: State, token: str):
    class Handler(BaseHTTPRequestHandler):
        server_version = "MDParkingBridge"
        sys_version = ""

        def _json(self, status: int, payload: object) -> None:
            body = json.dumps(payload, separators=(",", ":")).encode("utf-8")
            self.send_response(status)
            self.send_header("Content-Type", "application/json; charset=utf-8")
            self.send_header("Content-Length", str(len(body)))
            self.send_header("Cache-Control", "no-store")
            self.send_header("X-Content-Type-Options", "nosniff")
            self.end_headers()
            self.wfile.write(body)

        def _authorized(self) -> bool:
            supplied = self.headers.get("Authorization", "")
            return secrets.compare_digest(supplied, f"Bearer {token}")

        def _body(self) -> dict:
            try:
                length = int(self.headers.get("Content-Length", "0"))
            except ValueError as exc:
                raise ValueError("invalid content length") from exc
            if length < 0 or length > MAX_BODY_BYTES:
                raise ValueError("invalid body size")
            try:
                value = json.loads(self.rfile.read(length) or b"{}")
            except (json.JSONDecodeError, UnicodeDecodeError) as exc:
                raise ValueError("invalid JSON") from exc
            if not isinstance(value, dict):
                raise ValueError("invalid JSON shape")
            return value

        @property
        def route(self) -> str:
            return urlsplit(self.path).path

        def do_POST(self) -> None:  # noqa: N802
            if self.route == "/v1/pair":
                if not state.pairing_enabled:
                    self._json(HTTPStatus.CONFLICT, {"error": "pairing_unavailable"})
                    return
                with state.lock:
                    state.paired = True
                    PAIRING_FILE.write_text("paired", encoding="utf-8")
                    PAIRING_FILE.chmod(0o600)
                LOG.info("local pairing token issued while pairing window is enabled")
                self._json(HTTPStatus.OK, {"api_token": token})
                return
            if not self._authorized():
                self._json(HTTPStatus.UNAUTHORIZED, {"error": "unauthorized"})
                return
            try:
                data = self._body()
                if self.route == "/v1/auth/request-code":
                    status = state.request_code(
                        str(data["phone"]),
                        str(data["object_id"]) if data.get("object_id") else None,
                    )
                    self._json(HTTPStatus.OK, {"status": status})
                    return
                if self.route == "/v1/auth/authorize":
                    state.authorize(
                        str(data["phone"]),
                        str(data["object_id"]),
                        str(data["code"]),
                    )
                    self._json(HTTPStatus.OK, state.diagnostics())
                    return
                match = re.fullmatch(r"/v1/barriers/([^/]+)/open", self.route)
                if match:
                    if state.bridge is None:
                        self._json(
                            HTTPStatus.SERVICE_UNAVAILABLE,
                            {"error": "bridge_unavailable"},
                        )
                        return
                    try:
                        with state.lock:
                            event = state.control.open(
                                state.bridge,
                                match.group(1),
                                data.get("confirm") is True,
                            )
                        self._json(HTTPStatus.OK, {"status": event["result"]})
                    except RateLimited as exc:
                        self._json(
                            HTTPStatus.TOO_MANY_REQUESTS,
                            {
                                "error": exc.safe_code,
                                "retry_after": exc.retry_after,
                            },
                        )
                    except (ControlDisabled, ConfirmationRequired) as exc:
                        self._json(HTTPStatus.CONFLICT, {"error": exc.safe_code})
                    except KeyError:
                        self._json(HTTPStatus.NOT_FOUND, {"error": "unknown_barrier"})
                    except (ControlError, ProviderError) as exc:
                        self._json(HTTPStatus.BAD_GATEWAY, {"error": exc.safe_code})
                    return
                self._json(HTTPStatus.NOT_FOUND, {"error": "not_found"})
            except ProviderError as exc:
                LOG.warning("provider auth request failed: %s", exc.safe_code)
                self._json(
                    HTTPStatus.BAD_REQUEST,
                    {"error": "provider_auth_failed", "reason": exc.safe_code},
                )
            except (KeyError, TypeError, ValueError):
                LOG.warning("provider auth request failed: invalid_input")
                self._json(
                    HTTPStatus.BAD_REQUEST,
                    {"error": "provider_auth_failed", "reason": "invalid_input"},
                )

        def do_GET(self) -> None:  # noqa: N802
            if self.route == "/health":
                self._json(
                    HTTPStatus.OK,
                    {"status": "ok", "ready": state.auth_state == "authenticated"},
                )
                return
            if not self._authorized():
                self._json(HTTPStatus.UNAUTHORIZED, {"error": "unauthorized"})
                return
            if self.route == "/diagnostics":
                self._json(HTTPStatus.OK, state.diagnostics())
                return
            if self.route == "/v1/cameras":
                cameras = state.bridge.cameras.values() if state.bridge else []
                self._json(
                    HTTPStatus.OK,
                    {
                        "cameras": [
                            {
                                "id": camera.stream_name,
                                "name": camera.name,
                                "stream_name": camera.stream_name,
                                "available": camera.last_error is None
                                and camera.refreshed_at > 0,
                            }
                            for camera in cameras
                        ]
                    },
                )
                return
            if self.route == "/v1/barriers":
                barriers = state.bridge.barriers.values() if state.bridge else []
                self._json(
                    HTTPStatus.OK,
                    {
                        "control_enabled": state.control.enabled,
                        "barriers": [
                            {"id": barrier.barrier_id, "name": barrier.name}
                            for barrier in barriers
                        ],
                    },
                )
                return
            if self.route == "/v1/control-audit":
                self._json(HTTPStatus.OK, {"events": state.control.audit()})
                return
            self._json(HTTPStatus.NOT_FOUND, {"error": "not_found"})

        def do_PUT(self) -> None:  # noqa: N802
            self._json(HTTPStatus.METHOD_NOT_ALLOWED, {"error": "method_not_allowed"})

        do_DELETE = do_PUT
        do_PATCH = do_PUT

        def log_message(self, fmt: str, *args: object) -> None:
            LOG.info("local_api " + fmt, *args)

    return Handler


def _load_or_create_token() -> str:
    configured = os.environ.get("API_TOKEN", "").strip()
    if configured:
        return configured
    try:
        existing = TOKEN_FILE.read_text(encoding="utf-8").strip()
    except (FileNotFoundError, OSError, UnicodeDecodeError):
        existing = ""
    if existing:
        return existing
    token = secrets.token_urlsafe(32)
    TOKEN_FILE.write_text(token, encoding="utf-8")
    TOKEN_FILE.chmod(0o600)
    return token


def main() -> None:
    logging.basicConfig(
        level=logging.INFO, format="%(levelname)s %(name)s: %(message)s"
    )
    state = State()
    server = BridgeHttpServer(
        ("0.0.0.0", 8099), handler_factory(state, _load_or_create_token())
    )
    LOG.info("local API listening on port 8099 (version %s)", VERSION)
    try:
        server.serve_forever()
    except KeyboardInterrupt:
        pass
    finally:
        server.server_close()


if __name__ == "__main__":
    main()
